class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        stack = []
        for a in asteroids:
            alive = True
            while alive and a < 0 and stack and stack[-1] > 0:   # right-mover meets left-mover
                if stack[-1] < -a:
                    stack.pop()              # top explodes, keep checking
                elif stack[-1] == -a:
                    stack.pop()              # both explode
                    alive = False
                else:
                    alive = False            # incoming explodes
            if alive:
                stack.append(a)
        return stack
